import React, { useRef } from 'react';
import { useIntl } from 'react-intl';

import { CrosshairIcon } from '@dynatrace/strato-icons';

import { ChartToolbarRenderer } from '../../../core/components/toolbar/ChartToolbarRenderer.js';
import { isExplore } from '../../../core/functions/toolbarEvents.js';
import { useA11yToolbarTabIndex } from '../../../core/hooks/useA11yToolbarTabIndex.js';
import { useButtonKeyboardFocus } from '../../../core/hooks/useButtonKeyboardFocus.js';
import { useOverlaysEvents } from '../../../core/hooks/useOverlaysEvents.js';
import { useToolbarEvent } from '../../../core/hooks/useToolbarEvent.js';
import { useSetState, useZoomState } from '../../hooks/store/selectors.js';
import { useChartInteractions } from '../../hooks/useChartInteractions.js';
import { TIMESERIES_MESSAGES } from '../../messages/tooltips-text.js';

export const ExploreButton = () => {
  const EXPLORE_MODE = 'explore';
  const exploreButtonRef = useRef<HTMLButtonElement>();
  const intl = useIntl();
  const setState = useSetState();
  const tabIndex = useA11yToolbarTabIndex(EXPLORE_MODE);
  const { keyboardFocusMode, zoomMode } = useZoomState();
  const shouldFocusButton = EXPLORE_MODE === keyboardFocusMode;
  const { zoomX } = useChartInteractions();
  const isZoomXEnabled = zoomX?.enabled;
  const { isInChartBounds, overlayRef } = useOverlaysEvents();

  useButtonKeyboardFocus(exploreButtonRef, shouldFocusButton, handleFocus);

  function handleFocus() {
    setState((prev) => ({
      ...prev,
      zoom: {
        ...prev.zoom,
        keyboardFocusMode: undefined,
      },
    }));
  }

  /** Handles the zoom explore when an 'enter' keyboard event happens.
   * @param event - A keyboard event param.
   */
  function handleExploreKeyboardMode(event: KeyboardEvent) {
    if (event.key === 'Enter') {
      handleExploreToolbarMode(true);
    }
  }

  /** Handles the zoom explore mode when it's selected.*/
  function handleExploreToolbarMode(isKeyboardMode: boolean = false) {
    setState((prev) => ({
      ...prev,
      overlays: {
        ...prev.overlays,
        pinnedTooltip: false,
        visibleTooltip: false,
      },
      zoom: {
        ...prev.zoom,
        zoomMode: EXPLORE_MODE,
        activeKeyboardMode: isKeyboardMode ? EXPLORE_MODE : undefined,
      },
    }));
  }

  useToolbarEvent<KeyboardEvent>(
    'keydown',
    () => handleExploreToolbarMode(true),
    isExplore,
    isInChartBounds && isZoomXEnabled,
    overlayRef?.current as HTMLDivElement,
  );

  return (
    <ChartToolbarRenderer.Control
      ref={exploreButtonRef}
      prefixIcon={<CrosshairIcon />}
      tooltipText={intl.formatMessage(TIMESERIES_MESSAGES.zoomModeExplore)}
      tooltipKeyShortcut="E"
      selected={zoomMode === EXPLORE_MODE}
      onKeyDown={handleExploreKeyboardMode}
      onClick={() => handleExploreToolbarMode()}
      tabIndex={tabIndex}
    />
  );
};
ExploreButton['displayName'] = 'ExploreButton';
